<?php
if (!defined('ABSPATH')) exit;

/* FormPilot Scheduling Suite: real reusable event types, availability, bookings, teams,
 * routing, workflows, polls, single-use links, contacts, analytics and webhooks. */
function fp_sched_tables(){ global $wpdb; return [
 'events'=>$wpdb->prefix.'fp_events','availability'=>$wpdb->prefix.'fp_availability','bookings'=>$wpdb->prefix.'fp_bookings',
 'teams'=>$wpdb->prefix.'fp_teams','team_members'=>$wpdb->prefix.'fp_team_members','routing'=>$wpdb->prefix.'fp_routing',
 'polls'=>$wpdb->prefix.'fp_polls','poll_options'=>$wpdb->prefix.'fp_poll_options','poll_votes'=>$wpdb->prefix.'fp_poll_votes',
 'links'=>$wpdb->prefix.'fp_single_links','workflows'=>$wpdb->prefix.'fp_workflows','contacts'=>$wpdb->prefix.'fp_contacts',
 'events_log'=>$wpdb->prefix.'fp_event_log','webhooks'=>$wpdb->prefix.'fp_webhooks'
]; }
function fp_sched_install(){ global $wpdb; require_once ABSPATH.'wp-admin/includes/upgrade.php'; $c=$wpdb->get_charset_collate(); $t=fp_sched_tables();
 dbDelta("CREATE TABLE {$t['events']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, slug varchar(190) NOT NULL, title varchar(190) NOT NULL, description text NULL, type varchar(30) NOT NULL DEFAULT 'one_on_one', duration smallint unsigned NOT NULL DEFAULT 30, buffer_before smallint unsigned NOT NULL DEFAULT 0, buffer_after smallint unsigned NOT NULL DEFAULT 0, location_type varchar(30) NOT NULL DEFAULT 'custom', location_value text NULL, timezone varchar(80) NOT NULL DEFAULT 'UTC', active tinyint(1) NOT NULL DEFAULT 1, capacity smallint unsigned NOT NULL DEFAULT 1, host_mode varchar(30) NOT NULL DEFAULT 'owner', host_ids text NULL, settings longtext NULL, created_at datetime NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY user_slug(user_id,slug), KEY active(active), KEY type(type)) {$c};");
 dbDelta("CREATE TABLE {$t['availability']} (id bigint unsigned NOT NULL AUTO_INCREMENT, event_id bigint unsigned NOT NULL, weekday tinyint unsigned NOT NULL, start_time time NOT NULL, end_time time NOT NULL, PRIMARY KEY(id), KEY event_id(event_id), KEY weekday(weekday)) {$c};");
 dbDelta("CREATE TABLE {$t['bookings']} (id bigint unsigned NOT NULL AUTO_INCREMENT, event_id bigint unsigned NOT NULL, host_user_id bigint unsigned NOT NULL DEFAULT 0, invitee_name varchar(190) NOT NULL, invitee_email varchar(190) NOT NULL, invitee_phone varchar(50) NOT NULL DEFAULT '', start_at datetime NOT NULL, end_at datetime NOT NULL, timezone varchar(80) NOT NULL DEFAULT 'UTC', status varchar(20) NOT NULL DEFAULT 'scheduled', location text NULL, answers longtext NULL, payment_status varchar(20) NOT NULL DEFAULT 'none', payment_amount decimal(12,2) NOT NULL DEFAULT 0, external_id varchar(190) NOT NULL DEFAULT '', created_at datetime NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY(id), KEY event_start(event_id,start_at), KEY host_start(host_user_id,start_at), KEY email(invitee_email), KEY status(status)) {$c};");
 dbDelta("CREATE TABLE {$t['teams']} (id bigint unsigned NOT NULL AUTO_INCREMENT, owner_id bigint unsigned NOT NULL, name varchar(190) NOT NULL, slug varchar(190) NOT NULL, created_at datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY owner_slug(owner_id,slug)) {$c};");
 dbDelta("CREATE TABLE {$t['team_members']} (id bigint unsigned NOT NULL AUTO_INCREMENT, team_id bigint unsigned NOT NULL, user_id bigint unsigned NOT NULL, role varchar(30) NOT NULL DEFAULT 'member', weight smallint unsigned NOT NULL DEFAULT 1, active tinyint(1) NOT NULL DEFAULT 1, last_assigned_at datetime NULL, PRIMARY KEY(id), UNIQUE KEY team_user(team_id,user_id), KEY team_id(team_id)) {$c};");
 dbDelta("CREATE TABLE {$t['routing']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, name varchar(190) NOT NULL, slug varchar(190) NOT NULL, questions longtext NULL, rules longtext NULL, default_event_id bigint unsigned NOT NULL DEFAULT 0, active tinyint(1) NOT NULL DEFAULT 1, created_at datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY user_slug(user_id,slug)) {$c};");
 dbDelta("CREATE TABLE {$t['polls']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, title varchar(190) NOT NULL, description text NULL, duration smallint unsigned NOT NULL DEFAULT 30, timezone varchar(80) NOT NULL DEFAULT 'UTC', status varchar(20) NOT NULL DEFAULT 'open', created_at datetime NOT NULL, PRIMARY KEY(id)) {$c};");
 dbDelta("CREATE TABLE {$t['poll_options']} (id bigint unsigned NOT NULL AUTO_INCREMENT, poll_id bigint unsigned NOT NULL, start_at datetime NOT NULL, end_at datetime NOT NULL, PRIMARY KEY(id), KEY poll_id(poll_id)) {$c};");
 dbDelta("CREATE TABLE {$t['poll_votes']} (id bigint unsigned NOT NULL AUTO_INCREMENT, poll_id bigint unsigned NOT NULL, option_id bigint unsigned NOT NULL, voter_name varchar(190) NOT NULL, voter_email varchar(190) NOT NULL, vote tinyint(1) NOT NULL DEFAULT 1, created_at datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY voter_option(poll_id,option_id,voter_email)) {$c};");
 dbDelta("CREATE TABLE {$t['links']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, event_id bigint unsigned NOT NULL, token varchar(64) NOT NULL, max_uses smallint unsigned NOT NULL DEFAULT 1, uses smallint unsigned NOT NULL DEFAULT 0, expires_at datetime NULL, created_at datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY token(token)) {$c};");
 dbDelta("CREATE TABLE {$t['workflows']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, name varchar(190) NOT NULL, trigger_key varchar(80) NOT NULL, delay_minutes int NOT NULL DEFAULT 0, action_key varchar(80) NOT NULL, action_data longtext NULL, active tinyint(1) NOT NULL DEFAULT 1, created_at datetime NOT NULL, PRIMARY KEY(id), KEY user_trigger(user_id,trigger_key)) {$c};");
 dbDelta("CREATE TABLE {$t['contacts']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, name varchar(190) NOT NULL, email varchar(190) NOT NULL, phone varchar(50) NOT NULL DEFAULT '', company varchar(190) NOT NULL DEFAULT '', notes text NULL, last_booking_at datetime NULL, created_at datetime NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY user_email(user_id,email)) {$c};");
 dbDelta("CREATE TABLE {$t['events_log']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL DEFAULT 0, event_key varchar(80) NOT NULL, object_id bigint unsigned NOT NULL DEFAULT 0, meta longtext NULL, created_at datetime NOT NULL, PRIMARY KEY(id), KEY event_key(event_key), KEY created_at(created_at)) {$c};");
 dbDelta("CREATE TABLE {$t['webhooks']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, url text NOT NULL, secret varchar(190) NOT NULL DEFAULT '', events longtext NULL, active tinyint(1) NOT NULL DEFAULT 1, created_at datetime NOT NULL, PRIMARY KEY(id)) {$c};");
}
register_activation_hook(SSB_PLUGIN_FILE,'fp_sched_install');
add_action('admin_init',function(){ global $wpdb; $t=fp_sched_tables(); foreach($t as $x){ if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$x))!==$x){ fp_sched_install(); break; } } });

function fp_sched_feature($feature){ return function_exists('ssb_license_can') ? ssb_license_can($feature) : true; }
function fp_sched_gate($feature){ if(fp_sched_feature($feature)) return true; wp_die(esc_html(ssb_feature_locked_message($feature))); }
function fp_sched_slug($title){ $s=sanitize_title($title); return $s.'-'.substr(wp_generate_password(8,false,false),0,4); }
function fp_sched_now(){ return current_time('mysql'); }
function fp_sched_event($id){ global $wpdb; $t=fp_sched_tables(); return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['events']} WHERE id=%d",$id)); }
function fp_sched_event_settings($e){ $x=json_decode($e->settings,true); return is_array($x)?$x:[]; }
function fp_sched_log($key,$object=0,$meta=[],$user=0){ global $wpdb;$t=fp_sched_tables();$wpdb->insert($t['events_log'],['user_id'=>$user?:get_current_user_id(),'event_key'=>$key,'object_id'=>$object,'meta'=>wp_json_encode($meta),'created_at'=>fp_sched_now()]); }
function fp_sched_webhook($event,$payload){ if(function_exists('fp_adv_webhook_enqueue')){ fp_adv_webhook_enqueue($event,$payload); return; } global $wpdb;$t=fp_sched_tables();$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['webhooks']} WHERE active=1 AND (events IS NULL OR events='' OR events LIKE %s)",'%\"'.$wpdb->esc_like($event).'\"%')); foreach($rows as $w){ $body=wp_json_encode(['event'=>$event,'data'=>$payload,'sent_at'=>time()]); $sig=$w->secret?hash_hmac('sha256',$body,$w->secret):''; wp_remote_post($w->url,['timeout'=>8,'headers'=>['Content-Type'=>'application/json','X-FormPilot-Signature'=>$sig],'body'=>$body]); } }
function fp_sched_send_email($to,$subject,$body){ if(!$to)return; wp_mail($to,$subject,$body,['Content-Type: text/html; charset=UTF-8']); }
function fp_sched_upsert_contact($name,$email,$phone='',$company='',$user=0){ global $wpdb;$t=fp_sched_tables();$user=$user?:get_current_user_id();$now=fp_sched_now();$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['contacts']} WHERE user_id=%d AND email=%s",$user,$email)); if($row){$wpdb->update($t['contacts'],['name'=>$name,'phone'=>$phone,'company'=>$company,'last_booking_at'=>$now,'updated_at'=>$now],['id'=>$row->id]);return $row->id;} $wpdb->insert($t['contacts'],['user_id'=>$user,'name'=>$name,'email'=>$email,'phone'=>$phone,'company'=>$company,'last_booking_at'=>$now,'created_at'=>$now,'updated_at'=>$now]);return (int)$wpdb->insert_id; }

function fp_sched_available_slots($event_id,$date){ global $wpdb;$e=fp_sched_event($event_id);if(!$e||!$e->active)return []; try{$tz=new DateTimeZone($e->timezone?:wp_timezone_string());$d=new DateTime($date.' 00:00:00',$tz);}catch(Exception $x){return [];} $weekday=(int)$d->format('w');$t=fp_sched_tables();$windows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['availability']} WHERE event_id=%d AND weekday=%d ORDER BY start_time",$event_id,$weekday));$slots=[];$dur=(int)$e->duration;$before=(int)$e->buffer_before;$after=(int)$e->buffer_after;$step=max(5,$dur+$before+$after);foreach($windows as $w){$start=new DateTime($date.' '.$w->start_time,$tz);$end=new DateTime($date.' '.$w->end_time,$tz);for($cur=clone $start;$cur < $end;$cur->modify('+'.$step.' minutes')){$slot_end=(clone $cur)->modify('+'.$dur.' minutes');if($slot_end>$end)break;if($cur->getTimestamp()<=time())continue;$utc_start=(clone $cur)->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$utc_end=(clone $slot_end)->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['bookings']} WHERE event_id=%d AND start_at=%s AND status IN ('scheduled','pending')",$event_id,$utc_start));if($e->type==='group'&&$count >= (int)$e->capacity)continue;if($e->type!=='group'&&$count>0)continue;$hosts=fp_sched_hosts_for_slot($e,$utc_start,$utc_end);if(!$hosts)continue;$slots[]=['start'=>$cur->format('Y-m-d H:i:s'),'end'=>$slot_end->format('Y-m-d H:i:s'),'host_id'=>(int)$hosts[0],'host_ids'=>array_values(array_map('intval',$hosts)),'remaining'=>$e->type==='group'?max(0,(int)$e->capacity-$count):1];}}return $slots; }
function fp_sched_hosts_for_slot($e,$start,$end){ global $wpdb;$t=fp_sched_tables();$ids=[];if($e->type==='one_on_one'||$e->host_mode==='owner')$ids=[(int)$e->user_id];else{$ids=array_values(array_filter(array_unique(array_map('absint',preg_split('/\s*,\s*/',(string)$e->host_ids)))));if(!$ids)$ids=[(int)$e->user_id];} if($e->type==='group'){ $existing=$wpdb->get_var($wpdb->prepare("SELECT host_user_id FROM {$t['bookings']} WHERE event_id=%d AND start_at=%s AND status IN ('scheduled','pending') LIMIT 1",$e->id,$start)); if($existing)return [(int)$existing]; } $valid=[];foreach($ids as $id)if(fp_sched_host_conflict($id,$start,$end))$valid[]=$id;if($e->type==='collective')return count($valid)===count($ids)?$valid:[];if($e->type==='round_robin'&&count($valid)>1){$rank=[];foreach($valid as $id){$last=$wpdb->get_var($wpdb->prepare("SELECT MAX(created_at) FROM {$t['bookings']} WHERE host_user_id=%d AND status IN ('scheduled','completed')",$id));$rank[$id]=$last?strtotime($last):0;}usort($valid,function($a,$b)use($rank){if($rank[$a]===$rank[$b])return $a<=>$b;return $rank[$a]<=>$rank[$b];});}return $valid;}
function fp_sched_host_conflict($host,$start,$end){global $wpdb;$t=fp_sched_tables();$available=!(bool)$wpdb->get_var($wpdb->prepare("SELECT id FROM {$t['bookings']} WHERE host_user_id=%d AND status IN ('scheduled','pending') AND start_at < %s AND end_at > %s LIMIT 1",$host,$end,$start));if($available&&function_exists('fp_adv_tables')){$a=fp_adv_tables();if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$a['booking_hosts']))===$a['booking_hosts']){$available=!(bool)$wpdb->get_var($wpdb->prepare("SELECT b.id FROM {$t['bookings']} b JOIN {$a['booking_hosts']} h ON h.booking_id=b.id WHERE h.user_id=%d AND b.status IN ('scheduled','pending') AND b.start_at < %s AND b.end_at > %s LIMIT 1",$host,$end,$start));}}return (bool)apply_filters('fp_sched_host_available',$available,$host,$start,$end);}
function fp_sched_booking_create($event,$name,$email,$phone,$start_local,$answers=[],$payment_intent_id=''){global $wpdb;$t=fp_sched_tables();try{$tz=new DateTimeZone($event->timezone?:wp_timezone_string());$start=new DateTime($start_local,$tz);}catch(Exception $x){return new WP_Error('invalid_time','Invalid booking time.');}$end=(clone $start)->modify('+'.(int)$event->duration.' minutes');$utc=(clone $start)->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$utc_end=(clone $end)->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');if(strtotime($utc.' UTC')<=time())return new WP_Error('past_time','Please choose a future time.');$pay=true;if(function_exists('fp_adv_verify_payment')){$pay=fp_adv_verify_payment($event,$payment_intent_id);if(is_wp_error($pay))return $pay;}$lock='fp_'.md5($event->id.'|'.$utc);$got=(int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,3)',$lock));if(!$got)return new WP_Error('busy','This slot is being booked. Please retry.');try{$hosts=fp_sched_hosts_for_slot($event,$utc,$utc_end);if(!$hosts)return new WP_Error('slot_unavailable','That time is no longer available.');$host=(int)$hosts[0];if(function_exists('ssb_is_paid')&&!ssb_is_paid()){ $month=wp_date('Y-m-01 00:00:00'); $free_count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE e.user_id=%d AND b.created_at >= %s",$event->user_id,$month)); if($free_count>=10)return new WP_Error('free_limit',''.ssb_free_limit_notice('bookings')); }$existing=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['bookings']} WHERE event_id=%d AND start_at=%s AND status IN ('scheduled','pending')",$event->id,$utc));if($event->type!=='group'&&$existing)return new WP_Error('slot_taken','That time is already booked.');if($event->type==='group'&&$existing >= (int)$event->capacity)return new WP_Error('slot_full','That group session is full.');$settings=fp_sched_event_settings($event);$location=$event->location_value;$manage=function_exists('fp_adv_manage_token')?fp_adv_manage_token():wp_generate_password(48,false,false);$amount=function_exists('fp_adv_event_price')?fp_adv_event_price($event):0;$currency=strtoupper($settings['currency']??'USD');$data=['event_id'=>$event->id,'host_user_id'=>$host,'invitee_name'=>$name,'invitee_email'=>$email,'invitee_phone'=>$phone,'start_at'=>$utc,'end_at'=>$utc_end,'timezone'=>$event->timezone,'status'=>'scheduled','location'=>$location,'answers'=>wp_json_encode($answers),'payment_status'=>$amount>0?'paid':'none','payment_amount'=>$amount,'external_id'=>'','created_at'=>fp_sched_now(),'updated_at'=>fp_sched_now()];if(function_exists('fp_adv_manage_token')){$data['manage_token']=$manage;$data['payment_intent_id']=$payment_intent_id;}$wpdb->insert($t['bookings'],$data);$id=(int)$wpdb->insert_id;if(!$id)return new WP_Error('booking_failed','Could not create booking.');if(function_exists('fp_adv_store_booking_hosts'))fp_adv_store_booking_hosts($id,$hosts);fp_sched_upsert_contact($name,$email,$phone,'',$event->user_id);fp_sched_log('booking.created',$id,['event_id'=>$event->id,'host_ids'=>$hosts],$event->user_id);fp_sched_webhook('booking.created',['id'=>$id,'event_id'=>$event->id,'name'=>$name,'email'=>$email,'start_at'=>$utc]);do_action('fp_sched_booking_created',$id);if($amount>0&&function_exists('fp_adv_create_invoice'))fp_adv_create_invoice($id,$payment_intent_id);$fresh=$wpdb->get_row($wpdb->prepare("SELECT location FROM {$t['bookings']} WHERE id=%d",$id));if($fresh&&!empty($fresh->location))$location=$fresh->location;$subject='Booking confirmed: '.$event->title;$when=wp_date('F j, Y g:i a',strtotime($utc.' UTC'),$tz);$manage_url=home_url('/?formpilot_manage='.$manage);fp_sched_send_email($email,$subject,'<p>Your booking is confirmed.</p><p><strong>'.esc_html($event->title).'</strong><br>'.esc_html($when).'</p><p>'.esc_html($location).'</p><p><a href="'.esc_url($manage_url).'">Cancel or reschedule</a></p>');return $id;}finally{$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));}}

/* Scheduling pages are registered centrally beneath the FormPilot Pro menu. */

function fp_sched_header($title){echo '<div class="wrap fp-scheduling-admin"><div class="fp-sched-header"><div><div class="fp-sched-kicker">FORMPILOT PRO</div><h1>'.esc_html($title).'</h1></div><a class="button fp-sched-view" href="'.esc_url(home_url('/')).'" target="_blank">View site</a></div>';}
function fp_sched_footer(){echo '</div>';}
function fp_sched_events_page(){
    if(!fp_sched_gate('core'))return;
    global $wpdb; $t=fp_sched_tables(); $uid=get_current_user_id(); $editing=absint($_GET['edit']??0);
    if(isset($_GET['delete_event'])&&check_admin_referer('fp_delete_event')){
        $id=absint($_GET['delete_event']);
        $owns=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['events']} WHERE id=%d AND user_id=%d",$id,$uid));
        if($owns){$wpdb->delete($t['availability'],['event_id'=>$id]);$wpdb->delete($t['events'],['id'=>$id,'user_id'=>$uid]);echo '<div class="notice notice-success is-dismissible"><p>Event type deleted.</p></div>';if($editing===$id)$editing=0;}
    }
    if(isset($_POST['fp_event_save'])&&check_admin_referer('fp_event')){
        $id=absint($_POST['id']??0);
        if(!fp_sched_feature('group_events')&&in_array(sanitize_key($_POST['type']??'one_on_one'),['group','collective','round_robin'],true)){echo '<div class="notice notice-error"><p>That event type requires a FormPilot Pro license.</p></div>';}
        else {
            if(!$id&&!ssb_is_paid()){
                $count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['events']} WHERE user_id=%d AND active=1",$uid));
                if($count>=1){echo '<div class="notice notice-warning"><p>'.esc_html(ssb_free_limit_notice('event_types')).'</p></div>';$id=0;}
            }
            if($id || !isset($count) || $count<1 || ssb_is_paid()){
                $type=sanitize_key($_POST['type']??'one_on_one');
                if($type!=='one_on_one'&&!fp_sched_feature($type==='group'?'group_events':($type==='collective'?'collective_events':'round_robin')))$type='one_on_one';
                $old=$id?fp_sched_event($id):null;
                $base_slug=sanitize_title($_POST['slug']??$_POST['title']??'event');
                $slug=$old?$old->slug:($base_slug.'-'.wp_rand(100,999));
                $data=['user_id'=>$uid,'slug'=>$slug,'title'=>sanitize_text_field($_POST['title']??'New Event'),'description'=>sanitize_textarea_field($_POST['description']??''),'type'=>$type,'duration'=>max(5,absint($_POST['duration']??30)),'buffer_before'=>absint($_POST['buffer_before']??0),'buffer_after'=>absint($_POST['buffer_after']??0),'location_type'=>sanitize_key($_POST['location_type']??'custom'),'location_value'=>sanitize_text_field($_POST['location_value']??''),'timezone'=>sanitize_text_field($_POST['timezone']??wp_timezone_string()),'active'=>isset($_POST['active'])?1:0,'capacity'=>max(1,absint($_POST['capacity']??1)),'host_mode'=>sanitize_key($_POST['host_mode']??'owner'),'host_ids'=>sanitize_text_field($_POST['host_ids']??''),'settings'=>wp_json_encode(['price'=>(float)($_POST['price']??0),'currency'=>sanitize_text_field($_POST['currency']??'USD')]),'updated_at'=>fp_sched_now()];
                if($id)$wpdb->update($t['events'],$data,['id'=>$id,'user_id'=>$uid]);else{$data['created_at']=fp_sched_now();$wpdb->insert($t['events'],$data);$id=(int)$wpdb->insert_id;}
                if($id){for($d=0;$d<7;$d++)$wpdb->delete($t['availability'],['event_id'=>$id,'weekday'=>$d]);foreach((array)($_POST['days']??[]) as $d=>$ranges){foreach((array)$ranges as $r){$parts=explode('|',sanitize_text_field($r));if(count($parts)===2)$wpdb->insert($t['availability'],['event_id'=>$id,'weekday'=>absint($d),'start_time'=>$parts[0].':00','end_time'=>$parts[1].':00']);}}
                    echo '<div class="notice notice-success is-dismissible"><p>Event type '.($old?'updated':'created').'.</p></div>'; $editing=$id;
                }
            }
        }
    }
    $edit=$editing?fp_sched_event($editing):null; $settings=$edit?fp_sched_event_settings($edit):[];
    $rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['events']} WHERE user_id=%d ORDER BY id DESC",$uid));
    fp_sched_header($edit?'Edit Event Type':'Event Types');
    echo '<div class="fp-event-hero"><div><div class="fp-eyebrow">SCHEDULING</div><h2>'.($edit?'Edit your event':'Create a reusable booking experience').'</h2><p>Build consultations, demos, interviews, group sessions, collective meetings or round-robin appointments. You can edit, pause, preview or delete any event type.</p></div><a class="button button-primary" href="'.esc_url(admin_url('admin.php?page=fp-scheduling')).'">'.($edit?'Create another event':'New event').'</a></div>';
    echo '<div class="card" style="max-width:980px;padding:24px;margin:18px 0"><form method="post">'.wp_nonce_field('fp_event','_wpnonce',true,false).'<input type="hidden" name="fp_event_save" value="1"><input type="hidden" name="id" value="'.(int)($edit->id??0).'">';
    echo '<div style="display:grid;grid-template-columns:2fr 1fr;gap:18px"><label><strong>Event name</strong><input class="large-text" name="title" required value="'.esc_attr($edit->title??'30-minute Consultation').'" placeholder="30-minute Consultation"></label><label><strong>Event type</strong><select name="type" class="large-text">';foreach(['one_on_one'=>'One-on-one','group'=>'Group','collective'=>'Collective','round_robin'=>'Round robin'] as $k=>$v)echo '<option value="'.$k.'" '.selected($edit->type??'one_on_one',$k,false).'>'.$v.'</option>';echo '</select></label></div>';
    echo '<p><label><strong>Description</strong><textarea class="large-text" rows="3" name="description" placeholder="What will happen in this meeting?">'.esc_textarea($edit->description??'').'</textarea></label></p>';
    echo '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:14px"><label>Duration<input type="number" name="duration" value="'.(int)($edit->duration??30).'" min="5" max="1440"></label><label>Capacity<input type="number" name="capacity" value="'.(int)($edit->capacity??1).'" min="1"></label><label>Buffer before<input type="number" name="buffer_before" value="'.(int)($edit->buffer_before??0).'" min="0"></label><label>Buffer after<input type="number" name="buffer_after" value="'.(int)($edit->buffer_after??0).'" min="0"></label></div>';
    echo '<div style="display:grid;grid-template-columns:1fr 2fr;gap:14px;margin-top:14px"><label>Timezone<input class="large-text" name="timezone" value="'.esc_attr($edit->timezone??wp_timezone_string()).'"></label><label>Location<select name="location_type" class="large-text"><option value="custom">Custom / existing URL</option><option value="meet" '.selected($edit->location_type??'','meet',false).'>Google Meet</option><option value="zoom" '.selected($edit->location_type??'','zoom',false).'>Zoom</option><option value="teams" '.selected($edit->location_type??'','teams',false).'>Microsoft Teams</option><option value="phone" '.selected($edit->location_type??'','phone',false).'>Phone</option></select><input class="large-text" name="location_value" value="'.esc_attr($edit->location_value??'').'" placeholder="URL, phone number or instructions"></label></div>';
    echo '<div style="display:grid;grid-template-columns:1fr 2fr;gap:14px;margin-top:14px"><label>Price<input type="number" step="0.01" min="0" name="price" value="'.esc_attr($settings['price']??0).'" placeholder="0.00"></label><label>Currency<input name="currency" value="'.esc_attr($settings['currency']??'USD').'"></label></div>';
    echo '<p><label>Host mode <select name="host_mode"><option value="owner" '.selected($edit->host_mode??'owner','owner',false).'>Owner</option><option value="team" '.selected($edit->host_mode??'','team',false).'>Host pool</option></select></label> <label>Host user IDs <input class="regular-text" name="host_ids" value="'.esc_attr($edit->host_ids??'').'" placeholder="12,15,18"></label></p>';
    echo '<h3>Weekly availability</h3><p class="description">Use one or more ranges per day. Example: 09:00|17:00.</p><table class="widefat striped"><tbody>';for($d=0;$d<7;$d++){ $dayname=wp_date('l',strtotime('2024-01-07 +'.$d.' days'));$vals=[];if($edit)$vals=$wpdb->get_col($wpdb->prepare("SELECT CONCAT(start_time,'|',end_time) FROM {$t['availability']} WHERE event_id=%d AND weekday=%d ORDER BY start_time",$edit->id,$d));if(!$vals)$vals=['09:00|17:00'];echo '<tr><td style="width:160px"><strong>'.esc_html($dayname).'</strong></td><td>';foreach($vals as $v){$parts=explode('|',$v);$v=(isset($parts[0])?substr($parts[0],0,5):'09:00').'|'.(isset($parts[1])?substr($parts[1],0,5):'17:00');echo '<input class="regular-text" name="days['.$d.'][]" value="'.esc_attr($v).'">';}echo '</td></tr>';}echo '</tbody></table><p><label><input type="checkbox" name="active" '.checked($edit?$edit->active:1,1,false).'> Published and bookable</label></p><p><button class="button button-primary button-large">'.($edit?'Save changes':'Create Event Type').'</button> '.($edit?'<a class="button button-secondary" href="'.esc_url(admin_url('admin.php?page=fp-scheduling')).'">Cancel</a>':'').'</p></form></div>';
    echo '<h2>Event types</h2><table class="widefat striped"><thead><tr><th>Event</th><th>Type</th><th>Duration</th><th>Status</th><th>Public page</th><th>Actions</th></tr></thead><tbody>';
    if(!$rows)echo '<tr><td colspan="6">No event types yet. Create your first one above.</td></tr>';
    foreach($rows as $e){$url=home_url('/?formpilot_event='.rawurlencode($e->slug));$editurl=admin_url('admin.php?page=fp-scheduling&edit='.(int)$e->id);$del=wp_nonce_url(admin_url('admin.php?page=fp-scheduling&delete_event='.(int)$e->id),'fp_delete_event');echo '<tr><td><strong>'.esc_html($e->title).'</strong><br><small>'.esc_html($e->description).'</small></td><td>'.esc_html(ucwords(str_replace('_',' ',$e->type))).'</td><td>'.(int)$e->duration.' min</td><td>'.($e->active?'<span class="fp-status is-connected">Active</span>':'<span class="fp-status is-off">Paused</span>').'</td><td><a href="'.esc_url($url).'" target="_blank">Preview ↗</a></td><td><a class="button button-small" href="'.esc_url($editurl).'">Edit</a> <a class="button button-small" href="'.esc_url($del).'" onclick="return confirm(\'Delete this event type? Existing bookings are retained, but the event will no longer be available.\');">Delete</a></td></tr>';}
    echo '</tbody></table>';fp_sched_footer();
}
function fp_sched_availability_page(){fp_sched_header('Availability');echo '<p>Availability is stored per event type. Edit the event type to change its weekly schedule. FormPilot evaluates host conflicts and existing bookings before exposing a slot.</p>';echo '<p><a class="button button-primary" href="'.esc_url(admin_url('admin.php?page=fp-scheduling')).'">Manage Event Types</a></p>';fp_sched_footer();}
function fp_sched_analytics_page(){
    if(!fp_sched_gate('analytics'))return;
    global $wpdb; $t=fp_sched_tables(); $uid=get_current_user_id();
    $days=min(365,max(7,absint($_GET['days']??30))); $since=time()-($days*DAY_IN_SECONDS);
    $native=[];
    $rows=$wpdb->get_results($wpdb->prepare("SELECT b.*,e.title FROM {$t['bookings']} b INNER JOIN {$t['events']} e ON e.id=b.event_id WHERE e.user_id=%d ORDER BY b.created_at DESC LIMIT 2000",$uid));
    foreach((array)$rows as $r){$native[]=$r;}
    $legacy=function_exists('fp_sched_legacy_appointment_rows')?fp_sched_legacy_appointment_rows($uid,'','',''):[];
    $all=array_merge($native,(array)$legacy); $total=0;$confirmed=0;$cancelled=0;$completed=0;$upcoming=0;$revenue=0;$paid=0;$unpaid=0;$daily=[];$event_counts=[];
    foreach($all as $b){$ts=strtotime($b->start_at.((($b->source??'')==='legacy')?'':' UTC'));$created=strtotime($b->created_at??$b->start_at);if($created<$since)continue;$total++;
        if(in_array($b->status,['scheduled','confirmed'],true))$confirmed++;if($b->status==='cancelled')$cancelled++;if($b->status==='completed')$completed++;if($ts>=time()&&!in_array($b->status,['cancelled','completed'],true))$upcoming++;
        $ps=strtolower((string)($b->payment_status??''));$amt=(float)($b->payment_amount??0);if(in_array($ps,['paid','succeeded','success','completed','captured','requires_capture'],true)){ $revenue+=$amt;$paid++; } elseif($amt>0){$unpaid++;}
        $day=wp_date('Y-m-d',$created,wp_timezone());if(!isset($daily[$day]))$daily[$day]=['bookings'=>0,'revenue'=>0];$daily[$day]['bookings']++;if(in_array($ps,['paid','succeeded','success','completed','captured','requires_capture'],true))$daily[$day]['revenue']+=$amt;
        $title=(string)($b->title??'Booking');if(!isset($event_counts[$title]))$event_counts[$title]=0;$event_counts[$title]++;
    }
    arsort($event_counts);ksort($daily); $daily_values=[];foreach($daily as $dv)$daily_values[]=(int)$dv['bookings'];$max=max(1,max($daily_values?:[1]));
    fp_sched_header('Analytics');
    echo '<div class="fp-analytics-app"><div class="fp-analytics-hero"><div><div class="fp-card-kicker">FORMPILOT PRO</div><h1>Analytics</h1><p>Understand bookings, payment activity and conversion trends across your scheduling and legacy booking forms.</p></div><form method="get"><input type="hidden" name="page" value="fp-analytics"><select name="days"><option value="30" '.selected($days,30,false).'>Last 30 days</option><option value="90" '.selected($days,90,false).'>Last 90 days</option><option value="180" '.selected($days,180,false).'>Last 180 days</option><option value="365" '.selected($days,365,false).'>Last 12 months</option></select><button class="button">Apply</button></form></div>';
    echo '<div class="fp-analytics-stats"><div><strong>'.(int)$total.'</strong><span>Bookings</span></div><div><strong>'.(int)$confirmed.'</strong><span>Confirmed</span></div><div><strong>'.(int)$upcoming.'</strong><span>Upcoming</span></div><div><strong>'.(int)$cancelled.'</strong><span>Cancelled</span></div><div><strong>$'.esc_html(number_format($revenue,2)).'</strong><span>Paid revenue</span></div><div><strong>'.(int)$unpaid.'</strong><span>Unpaid bookings</span></div></div>';
    echo '<div class="fp-analytics-grid"><section class="fp-analytics-card"><div class="fp-analytics-card-head"><div><h2>Booking activity</h2><p>Created bookings during the selected period.</p></div></div><div class="fp-bars">';if(!$daily)echo '<div class="fp-analytics-empty">No booking activity in this period.</div>';foreach($daily as $d=>$v){$h=max(8,round(($v['bookings']/$max)*150));echo '<div class="fp-bar-col" title="'.esc_attr($d.': '.$v['bookings'].' bookings · $'.number_format($v['revenue'],2)).'"><span style="height:'.$h.'px"></span><small>'.esc_html(wp_date('M j',strtotime($d),wp_timezone())).'</small></div>';}echo '</div></section>';
    echo '<section class="fp-analytics-card"><div class="fp-analytics-card-head"><div><h2>Booking status</h2><p>Current state of bookings created in this period.</p></div></div><div class="fp-status-list"><div><span>Confirmed</span><strong>'.(int)$confirmed.'</strong></div><div><span>Completed</span><strong>'.(int)$completed.'</strong></div><div><span>Cancelled</span><strong>'.(int)$cancelled.'</strong></div><div><span>Paid</span><strong>'.(int)$paid.'</strong></div></div></section></div>';
    echo '<div class="fp-analytics-grid"><section class="fp-analytics-card"><div class="fp-analytics-card-head"><div><h2>Top booking types</h2><p>Bookings grouped by event/form.</p></div></div><table class="widefat striped"><tbody>';if(!$event_counts)echo '<tr><td>No data yet.</td></tr>';foreach(array_slice($event_counts,0,10,true) as $name=>$count)echo '<tr><td><strong>'.esc_html($name).'</strong></td><td style="text-align:right">'.(int)$count.'</td></tr>';echo '</tbody></table></section>';
    echo '<section class="fp-analytics-card"><div class="fp-analytics-card-head"><div><h2>Payment health</h2><p>Unpaid amounts are not included in revenue.</p></div></div><div class="fp-payment-callout"><strong>$'.esc_html(number_format($revenue,2)).'</strong><span>recognized paid revenue</span><small>'.(int)$unpaid.' booking'.($unpaid===1?'':'s').' with a configured amount are still unpaid.</small></div></section></div></div>';
    echo '<style>.fp-analytics-app{max-width:1400px}.fp-analytics-hero{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:30px;border-radius:20px;background:linear-gradient(135deg,#111827,#312e81,#4f46e5);color:#fff;margin:8px 0 20px}.fp-analytics-hero h1{color:#fff;font-size:32px;margin:6px 0}.fp-analytics-hero p{color:#dbeafe;margin:0;max-width:760px}.fp-analytics-hero form{display:flex;gap:8px}.fp-analytics-hero select{min-width:150px}.fp-analytics-stats{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-bottom:16px}.fp-analytics-stats>div{background:#fff;border:1px solid #e5e7eb;border-radius:15px;padding:18px}.fp-analytics-stats strong{display:block;font-size:25px;color:#111827}.fp-analytics-stats span{color:#64748b;font-size:12px}.fp-analytics-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:16px;margin-bottom:16px}.fp-analytics-card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:20px}.fp-analytics-card h2{margin:0 0 5px;font-size:18px}.fp-analytics-card-head p{margin:0 0 18px;color:#64748b;font-size:13px}.fp-bars{height:190px;display:flex;align-items:flex-end;gap:7px;overflow-x:auto;padding:10px 0}.fp-bar-col{min-width:34px;height:175px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:6px}.fp-bar-col span{width:22px;background:#6366f1;border-radius:6px 6px 2px 2px;display:block}.fp-bar-col small{font-size:9px;color:#64748b;white-space:nowrap}.fp-status-list{display:grid;gap:10px}.fp-status-list div{display:flex;justify-content:space-between;padding:12px 14px;background:#f8fafc;border-radius:10px}.fp-status-list span{color:#64748b}.fp-payment-callout{display:flex;flex-direction:column;padding:25px;border-radius:14px;background:#f5f3ff}.fp-payment-callout strong{font-size:32px;color:#312e81}.fp-payment-callout span{font-weight:700}.fp-payment-callout small{color:#64748b;margin-top:8px}.fp-analytics-empty{color:#64748b;padding:50px}.fp-analytics-card table{border:0}.fp-analytics-card td{border-left:0;border-right:0}@media(max-width:1100px){.fp-analytics-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:800px){.fp-analytics-grid{grid-template-columns:1fr}.fp-analytics-hero{align-items:flex-start;flex-direction:column}}@media(max-width:600px){.fp-analytics-stats{grid-template-columns:repeat(2,1fr)}}</style>';
    fp_sched_footer();
}

function fp_sched_bookings_page(){
    if(!fp_sched_gate('bookings'))return;
    global $wpdb;$t=fp_sched_tables();$uid=get_current_user_id();
    $status=sanitize_key($_GET['status']??'');$q=sanitize_text_field(wp_unslash($_GET['s']??''));
    $date=sanitize_text_field(wp_unslash($_GET['date']??''));
    $where='e.user_id=%d';$args=[$uid];
    if($status){$where.=' AND b.status=%s';$args[]=$status;}
    if($q){$like='%'.$wpdb->esc_like($q).'%';$where.=' AND (b.invitee_name LIKE %s OR b.invitee_email LIKE %s OR b.invitee_phone LIKE %s OR e.title LIKE %s)';array_push($args,$like,$like,$like,$like);}
    if($date && preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$where.=' AND DATE(CONVERT_TZ(b.start_at,"+00:00",%s))=%s';$args[]=$date;/* MySQL may not have timezone tables; fallback below if needed. */$args[]=$date;}
    $sql="SELECT b.*,e.title,e.slug,e.timezone AS event_timezone,e.user_id AS event_owner FROM {$t['bookings']} b INNER JOIN {$t['events']} e ON e.id=b.event_id WHERE $where ORDER BY b.start_at DESC LIMIT 500";
    $bookings=$wpdb->get_results($wpdb->prepare($sql,$args));
    if($date && $wpdb->last_error){
        $where='e.user_id=%d';$args=[$uid];if($status){$where.=' AND b.status=%s';$args[]=$status;}if($q){$like='%'.$wpdb->esc_like($q).'%';$where.=' AND (b.invitee_name LIKE %s OR b.invitee_email LIKE %s OR b.invitee_phone LIKE %s OR e.title LIKE %s)';array_push($args,$like,$like,$like,$like);} $bookings=$wpdb->get_results($wpdb->prepare("SELECT b.*,e.title,e.slug,e.timezone AS event_timezone,e.user_id AS event_owner FROM {$t['bookings']} b INNER JOIN {$t['events']} e ON e.id=b.event_id WHERE $where ORDER BY b.start_at DESC LIMIT 500",$args));
    }
    $legacy_initial=fp_sched_legacy_appointment_rows($uid,$q,$status,$date);
    $bookings=array_merge((array)$bookings,$legacy_initial);
    usort($bookings,function($a,$b){ return strcmp((string)$b->start_at,(string)$a->start_at); });
    $total=count($bookings); $upcoming=0; $confirmed=0; $cancelled=0;
    foreach($bookings as $bk){
        $is_legacy=(($bk->source??'')==='legacy');
        $ts=strtotime($bk->start_at.($is_legacy?'':' UTC'));
        if($ts>=time() && !in_array($bk->status,['cancelled','completed'],true)) $upcoming++;
        if(in_array($bk->status,['scheduled','confirmed'],true)) $confirmed++;
        if($bk->status==='cancelled') $cancelled++;
    }
    $nonce=wp_create_nonce('fp_sched_booking_admin');
    fp_sched_header('Scheduling Bookings');
    ?>
    <div class="fp-bookings-app" data-nonce="<?php echo esc_attr($nonce); ?>" data-ajax="<?php echo esc_url(admin_url('admin-ajax.php')); ?>">
      <div class="fp-bookings-hero"><div><span class="fp-card-kicker">FORMPILOT PRO</span><h1>Bookings</h1><p>See every appointment, invitee, payment and meeting detail in one place.</p></div><div class="fp-bookings-live"><span></span> Live updates <em id="fp-booking-updated">Ready</em></div></div>
      <div class="fp-booking-stats">
        <div><strong data-stat="total"><?php echo $total;?></strong><span>Total bookings</span></div>
        <div><strong data-stat="upcoming"><?php echo $upcoming;?></strong><span>Upcoming</span></div>
        <div><strong data-stat="confirmed"><?php echo $confirmed;?></strong><span>Confirmed</span></div>
        <div><strong data-stat="cancelled"><?php echo $cancelled;?></strong><span>Cancelled</span></div>
        <div><strong data-stat="revenue">$<?php echo esc_html(number_format(array_sum(array_map(function($x){return ((float)($x->payment_amount??0)>0 && in_array(strtolower((string)($x->payment_status??'')),['paid','succeeded','success','completed','captured','requires_capture'],true))?(float)$x->payment_amount:0;},$bookings)),2));?></strong><span>Revenue</span></div>
      </div>
      <div class="fp-bookings-toolbar">
        <div class="fp-booking-search"><input id="fp-booking-search" type="search" value="<?php echo esc_attr($q);?>" placeholder="Search name, email, phone or event…"><button type="button" id="fp-booking-search-btn">Search</button></div>
        <select id="fp-booking-status"><option value="">All statuses</option><option value="scheduled" <?php selected($status,'scheduled');?>>Confirmed</option><option value="pending" <?php selected($status,'pending');?>>Pending</option><option value="cancelled" <?php selected($status,'cancelled');?>>Cancelled</option><option value="completed" <?php selected($status,'completed');?>>Completed</option></select>
        <input id="fp-booking-date" type="date" value="<?php echo esc_attr($date);?>">
        <button type="button" class="button" id="fp-booking-refresh">Refresh</button>
        <button type="button" class="button" id="fp-booking-calendar-toggle">Calendar</button>
      </div>
      <div id="fp-booking-loading" class="fp-booking-loading" hidden>Updating bookings…</div>
      <div id="fp-booking-list" class="fp-booking-list">
      <?php if(!$bookings): ?><div class="fp-booking-empty"><h2>No bookings yet</h2><p>When someone books one of your event types, their appointment will appear here with all submitted details.</p></div><?php else: foreach($bookings as $b):
          $is_legacy=(($b->source??'')==='legacy');$row_id=$is_legacy?'legacy-'.(($b->legacy_kind??'entry')).'-'.(int)$b->id:(string)(int)$b->id;$start=strtotime($b->start_at.($is_legacy?'':' UTC'));$initials=strtoupper(substr($b->invitee_name,0,1));$parts=preg_split('/\s+/',$b->invitee_name);if(count($parts)>1)$initials.=strtoupper(substr(end($parts),0,1));
          $answers=json_decode($b->answers,true);$answer_count=is_array($answers)?count($answers):0;
          $host=$b->host_user_id?get_userdata((int)$b->host_user_id):null;
          $when=wp_date('M j, Y · g:i A', $start, wp_timezone());
          $badge=in_array($b->status,['scheduled','pending','cancelled','completed'],true)?$b->status:'default';
      ?>
        <article class="fp-booking-row" data-id="<?php echo esc_attr($row_id);?>">
          <div class="fp-booking-avatar"><?php echo esc_html($initials);?></div>
          <div class="fp-booking-main"><div class="fp-booking-name"><strong><?php echo esc_html($b->invitee_name);?></strong><span class="fp-booking-badge <?php echo esc_attr($badge);?>"><?php echo esc_html(ucfirst($b->status));?></span></div><div class="fp-booking-event"><?php echo esc_html($b->title);?><?php if($is_legacy):?><span class="fp-source-pill">Form booking</span><?php endif;?></div><div class="fp-booking-meta"><span><?php echo esc_html($when);?></span><span><?php echo esc_html($b->event_timezone?:$b->timezone);?></span><?php if($host):?><span>Host: <?php echo esc_html($host->display_name);?></span><?php endif;?></div></div>
          <div class="fp-booking-contact"><a href="mailto:<?php echo esc_attr($b->invitee_email);?>"><?php echo esc_html($b->invitee_email);?></a><?php if($b->invitee_phone):?><a href="tel:<?php echo esc_attr($b->invitee_phone);?>"><?php echo esc_html($b->invitee_phone);?></a><?php endif;?></div>
          <div class="fp-booking-summary"><?php if(!empty($b->meeting_url)):?><a class="fp-meeting-btn" target="_blank" rel="noopener" href="<?php echo esc_url($b->meeting_url);?>">Join meeting</a><?php endif;?><span><?php echo esc_html($b->payment_status?:'unpaid');?></span><?php if((float)$b->payment_amount>0):?><strong><?php echo esc_html(number_format((float)$b->payment_amount,2));?></strong><?php endif;?><?php if($answer_count):?><small><?php echo $answer_count;?> form answer<?php echo $answer_count===1?'':'s';?></small><?php endif;?></div>
          <button type="button" class="button fp-booking-view" data-id="<?php echo esc_attr($row_id);?>">View details</button>
        </article>
      <?php endforeach;endif; ?>
      </div>
      <div id="fp-booking-calendar" class="fp-booking-calendar" hidden></div>
      <div id="fp-booking-modal" class="fp-booking-modal" hidden><div class="fp-booking-modal-backdrop"></div><div class="fp-booking-modal-card"><button type="button" class="fp-booking-modal-close" aria-label="Close">×</button><div id="fp-booking-detail"></div></div></div>
    </div>
    <style>
      .fp-bookings-app{max-width:1280px}.fp-bookings-hero{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:8px 0 22px;padding:28px 30px;border-radius:18px;background:linear-gradient(135deg,#111827,#26344d);color:#fff}.fp-bookings-hero h1{margin:5px 0 6px;font-size:32px}.fp-bookings-hero p{margin:0;color:#cbd5e1}.fp-bookings-live{background:rgba(255,255,255,.1);padding:9px 13px;border-radius:999px;font-size:12px}.fp-bookings-live span{display:inline-block;width:7px;height:7px;border-radius:50%;background:#34d399;margin-right:7px}.fp-booking-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:14px;margin-bottom:18px}.fp-booking-stats>div{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:18px 20px}.fp-booking-stats strong{display:block;font-size:27px}.fp-booking-stats span{color:#64748b;font-size:13px}.fp-bookings-toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:13px;margin-bottom:14px}.fp-booking-search{display:flex;flex:1;min-width:280px}.fp-booking-search input{flex:1;border:1px solid #d1d5db;border-radius:8px 0 0 8px;padding:9px 12px}.fp-booking-search button{border:0;border-radius:0 8px 8px 0;padding:0 15px;background:#111827;color:#fff}.fp-booking-list{display:grid;gap:10px}.fp-booking-row{display:grid;grid-template-columns:44px minmax(280px,1fr) minmax(220px,.8fr) 120px 110px;align-items:center;gap:16px;background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:16px;box-shadow:0 1px 2px rgba(15,23,42,.03)}.fp-booking-avatar{width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#eef2ff;color:#3730a3;font-weight:700}.fp-booking-name{display:flex;gap:8px;align-items:center}.fp-booking-event{font-weight:600;margin-top:4px}.fp-source-pill{display:inline-block;margin-left:7px;padding:3px 7px;border-radius:999px;background:#eef2ff;color:#4338ca;font-size:10px;font-weight:600}.fp-meeting-btn{display:inline-flex;align-items:center;justify-content:center;gap:5px;margin-bottom:6px;padding:7px 10px;border-radius:8px;background:#111827;color:#fff;text-decoration:none;font-size:11px;font-weight:600}.fp-meeting-btn:hover{color:#fff;opacity:.9}.fp-booking-meta{display:flex;gap:12px;flex-wrap:wrap;color:#64748b;font-size:12px;margin-top:5px}.fp-booking-badge{font-size:11px;padding:3px 7px;border-radius:999px;background:#e2e8f0}.fp-booking-badge.scheduled{background:#dcfce7;color:#166534}.fp-booking-badge.pending{background:#fef3c7;color:#92400e}.fp-booking-badge.cancelled{background:#fee2e2;color:#991b1b}.fp-booking-badge.completed{background:#dbeafe;color:#1d4ed8}.fp-booking-contact a{display:block;color:#334155;text-decoration:none;font-size:13px;overflow:hidden;text-overflow:ellipsis}.fp-booking-summary{text-align:right;color:#64748b;font-size:12px}.fp-booking-summary strong{display:block;color:#0f172a}.fp-booking-summary small{display:block;margin-top:4px}.fp-booking-empty{padding:70px 30px;text-align:center;background:#fff;border:1px dashed #cbd5e1;border-radius:16px}.fp-booking-loading{padding:8px 10px;color:#64748b;font-size:12px}.fp-booking-loading[hidden]{display:none}.fp-booking-list.fp-refreshing{opacity:.72;transition:opacity .2s}.fp-booking-updated{font-size:12px;color:#64748b;margin-left:auto}.fp-booking-modal{position:fixed;inset:0;z-index:100000}.fp-booking-modal[hidden]{display:none}.fp-booking-modal-backdrop{position:absolute;inset:0;background:rgba(15,23,42,.55)}.fp-booking-modal-card{position:relative;width:min(760px,calc(100% - 32px));max-height:calc(100vh - 60px);overflow:auto;margin:30px auto;background:#fff;border-radius:18px;padding:28px;box-shadow:0 20px 60px rgba(0,0,0,.25)}.fp-booking-modal-close{position:absolute;right:16px;top:10px;border:0;background:none;font-size:30px;color:#64748b;cursor:pointer}.fp-detail-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:20px 0}.fp-detail-card{border:1px solid #e5e7eb;border-radius:12px;padding:14px}.fp-detail-card small{display:block;color:#64748b;margin-bottom:5px}.fp-detail-answer{padding:12px 0;border-bottom:1px solid #e5e7eb}.fp-meeting-card{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:18px 0;padding:14px 16px;border:1px solid #dbeafe;border-radius:12px;background:#f8fbff}.fp-meeting-card strong{margin-right:auto}.fp-meeting-card code{width:100%;font-size:11px;overflow-wrap:anywhere}.fp-meeting-missing{border-color:#e5e7eb;background:#f8fafc}.fp-meeting-missing span{width:100%;color:#64748b;font-size:12px}.fp-detail-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px}.fp-booking-calendar{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:18px}.fp-calendar-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:8px}.fp-calendar-day{min-height:110px;border:1px solid #e5e7eb;border-radius:10px;padding:8px}.fp-calendar-day strong{font-size:12px}.fp-calendar-item{margin-top:7px;padding:6px;border-radius:7px;background:#eef2ff;color:#3730a3;font-size:11px;cursor:pointer}.fp-calendar-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}
