    <script>
    (function(){var app=document.querySelector('.fp-bookings-app');if(!app)return;var ajax=app.dataset.ajax,nonce=app.dataset.nonce,list=document.getElementById('fp-booking-list'),loading=document.getElementById('fp-booking-loading'),modal=document.getElementById('fp-booking-modal'),detail=document.getElementById('fp-booking-detail');
      function post(data){data.action='fp_sched_admin_bookings';data.nonce=nonce;return fetch(ajax,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'},body:new URLSearchParams(data)}).then(function(r){return r.json()});}
      function filters(){return {q:document.getElementById('fp-booking-search').value,status:document.getElementById('fp-booking-status').value,date:document.getElementById('fp-booking-date').value};}
      function escapeHtml(s){var d=document.createElement('div');d.textContent=s==null?'':String(s);return d.innerHTML;}
      var refreshTimer=0,requestBusy=false,lastUpdated=0;
      function load(silent){if(requestBusy)return;requestBusy=true;var f=filters(),timer=setTimeout(function(){if(!silent)loading.hidden=false;list.classList.add('fp-refreshing');},250);post({mode:'list',q:f.q,status:f.status,date:f.date}).then(function(r){clearTimeout(timer);loading.hidden=true;list.classList.remove('fp-refreshing');requestBusy=false;if(!r.success)return;document.querySelector('[data-stat="total"]').textContent=r.data.stats.total;document.querySelector('[data-stat="upcoming"]').textContent=r.data.stats.upcoming;document.querySelector('[data-stat="confirmed"]').textContent=r.data.stats.confirmed;document.querySelector('[data-stat="cancelled"]').textContent=r.data.stats.cancelled;var rev=document.querySelector('[data-stat="revenue"]');if(rev)rev.textContent='$'+Number(r.data.stats.revenue||0).toFixed(2);list.innerHTML=r.data.html;bindRows();lastUpdated=Date.now();var stamp=document.getElementById('fp-booking-updated');if(stamp)stamp.textContent='Updated just now';if(!document.getElementById('fp-booking-calendar').hidden)renderCalendar(r.data.bookings);}).catch(function(){clearTimeout(timer);loading.hidden=true;list.classList.remove('fp-refreshing');requestBusy=false;});}
      function scheduleRefresh(){clearTimeout(refreshTimer);if(document.hidden)return;refreshTimer=setTimeout(function(){load(true);scheduleRefresh();},60000);}
      function bindRows(){list.querySelectorAll('.fp-booking-view').forEach(function(b){b.onclick=function(){openDetail(b.dataset.id)}});}
      function openDetail(id){detail.innerHTML='<p>Loading booking…</p>';modal.hidden=false;post({mode:'detail',id:id}).then(function(r){if(!r.success){detail.innerHTML='<p>'+escapeHtml(r.data&&r.data.message||'Could not load booking.')+'</p>';return;}var b=r.data.booking,a=r.data.answers||{};var h='<span class="fp-card-kicker">BOOKING #'+escapeHtml(b.id)+'</span><h2>'+escapeHtml(b.invitee_name)+'</h2><p><strong>'+escapeHtml(b.title)+'</strong> · '+escapeHtml(b.status)+'</p><div class="fp-detail-grid">'+cell('Email','<a href="mailto:'+escapeHtml(b.invitee_email)+'">'+escapeHtml(b.invitee_email)+'</a>')+cell('Phone',b.invitee_phone?'<a href="tel:'+escapeHtml(b.invitee_phone)+'">'+escapeHtml(b.invitee_phone)+'</a>':'—')+cell('Date & time',escapeHtml(b.when))+cell('Timezone',escapeHtml(b.timezone||b.event_timezone))+cell('Host',escapeHtml(b.host||'Unassigned'))+cell('Location',escapeHtml(b.location||'Not specified'))+cell('Payment',escapeHtml(b.payment_status||'none')+(parseFloat(b.payment_amount)>0?' · '+escapeHtml(b.payment_amount):''))+cell('Created',escapeHtml(b.created));h+='</div>';if(b.meeting_url)h+='<p><strong>Meeting link</strong><br><a target="_blank" rel="noopener" href="'+escapeHtml(b.meeting_url)+'">'+escapeHtml(b.meeting_url)+'</a></p>';if(b.meeting_url)h+='<div class="fp-meeting-card"><strong>Google Meet</strong><a class="button button-primary" target="_blank" rel="noopener" href="'+escapeHtml(b.meeting_url)+'">Join meeting</a><code>'+escapeHtml(b.meeting_url)+'</code></div>';else if(b.calendar_url)h+='<div class="fp-meeting-card"><strong>Calendar event</strong><a class="button" target="_blank" rel="noopener" href="'+escapeHtml(b.calendar_url)+'">Open calendar event</a></div>';else h+='<div class="fp-meeting-card fp-meeting-missing"><strong>No meeting link attached</strong><span>Connect Google Calendar + Google Meet and enable it for this form to generate a join link for new appointments.</span></div>';h+='<h3>Form answers</h3>';if(Object.keys(a).length){Object.keys(a).forEach(function(k){h+='<div class="fp-detail-answer"><small>'+escapeHtml(k)+'</small><div>'+escapeHtml(typeof a[k]==='object'?JSON.stringify(a[k]):a[k])+'</div></div>';});}else h+='<p>No additional form answers were submitted.</p>';h+='<div class="fp-detail-actions">';if(b.status!=='cancelled'&&b.status!=='completed')h+='<button class="button" data-action="cancel" data-id="'+b.id+'">Cancel booking</button>';if(b.status==='pending')h+='<button class="button button-primary" data-action="confirm" data-id="'+b.id+'">Confirm booking</button>';if(b.status==='scheduled'||b.status==='confirmed'||b.status==='pending')h+='<button class="button button-primary" data-action="complete" data-id="'+b.id+'">Mark completed</button>';if(b.status==='completed')h+='<span class="description">Completed</span>';h+='</div>';detail.innerHTML=h;detail.querySelectorAll('[data-action]').forEach(function(x){x.onclick=function(){post({mode:'status',id:x.dataset.id,status:x.dataset.action==='cancel'?'cancelled':(x.dataset.action==='confirm'?'confirmed':'completed')}).then(function(z){if(z.success){openDetail(x.dataset.id);load();}});}});});}
      function cell(k,v){return '<div class="fp-detail-card"><small>'+k+'</small><div>'+v+'</div></div>';}
      function renderCalendar(rows){var box=document.getElementById('fp-booking-calendar'),by={};rows.forEach(function(b){var d=b.local_date;(by[d]||(by[d]=[])).push(b);});var keys=Object.keys(by).sort(),html='<div class="fp-calendar-head"><strong>Booked appointments</strong><span>'+keys.length+' day'+(keys.length===1?'':'s')+'</span></div><div class="fp-calendar-grid">';if(!keys.length)html+='<div class="fp-booking-empty" style="grid-column:1/-1">No bookings in the current filter.</div>';keys.forEach(function(d){html+='<div class="fp-calendar-day"><strong>'+escapeHtml(d)+'</strong>';by[d].forEach(function(b){html+='<div class="fp-calendar-item" data-cal-id="'+b.id+'">'+escapeHtml(b.local_time)+' · '+escapeHtml(b.invitee_name)+'<br>'+escapeHtml(b.title)+'</div>';});html+='</div>';});box.innerHTML=html;box.querySelectorAll('[data-cal-id]').forEach(function(x){x.onclick=function(){openDetail(x.dataset.calId)}});}
      document.getElementById('fp-booking-search-btn').onclick=load;document.getElementById('fp-booking-refresh').onclick=load;document.getElementById('fp-booking-status').onchange=load;document.getElementById('fp-booking-date').onchange=load;document.getElementById('fp-booking-search').onkeydown=function(e){if(e.key==='Enter'){e.preventDefault();load();}};document.getElementById('fp-booking-calendar-toggle').onclick=function(){var c=document.getElementById('fp-booking-calendar');var show=c.hidden;c.hidden=!show;list.hidden=show;this.textContent=show?'List':'Calendar';if(show)post(Object.assign({mode:'calendar'},filters())).then(function(r){if(r.success)renderCalendar(r.data.bookings);});};modal.querySelector('.fp-booking-modal-backdrop').onclick=function(){modal.hidden=true};modal.querySelector('.fp-booking-modal-close').onclick=function(){modal.hidden=true};bindRows();document.addEventListener('visibilitychange',function(){if(document.hidden){clearTimeout(refreshTimer);}else{load(true);scheduleRefresh();}});scheduleRefresh();
    })();
    </script>
    <?php fp_sched_footer();
}


/* Unified booking feed: combines the native scheduling engine with legacy
 * [smart_schedule_booking] form submissions that contain appointment fields. */

