function fp_sched_contacts_page(){
    if(!fp_sched_gate('contacts'))return; global $wpdb;$t=fp_sched_tables();$u=get_current_user_id();
    $rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['contacts']} WHERE user_id=%d ORDER BY last_booking_at DESC, id DESC LIMIT 500",$u));
    fp_sched_header('Contacts'); echo '<div class="fp-admin-panel"><p>Contacts captured from FormPilot bookings and forms.</p><table class="widefat striped"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Last booking</th><th>Created</th></tr></thead><tbody>';
    if(!$rows)echo '<tr><td colspan="5">No contacts yet.</td></tr>'; foreach($rows as $r)echo '<tr><td><strong>'.esc_html($r->name).'</strong></td><td>'.esc_html($r->email).'</td><td>'.esc_html($r->phone).'</td><td>'.esc_html($r->last_booking_at?:'—').'</td><td>'.esc_html($r->created_at).'</td></tr>'; echo '</tbody></table></div>'; fp_sched_footer();
}
