function fp_sched_legacy_appointment_rows($uid, $q='', $status='', $date_filter='') {
    global $wpdb;
    $forms_table=$wpdb->prefix.'ssb_forms'; $entries_table=$wpdb->prefix.'ssb_form_entries'; $old_table=$wpdb->prefix.'schedule_bookings';
    $has_forms=(bool)$wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s",$forms_table));
    $has_entries=(bool)$wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s",$entries_table));
    $has_old=(bool)$wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s",$old_table));
    if(!$has_forms && !$has_old) return [];
    $out=[]; $tz=wp_timezone(); $old_index=[];
    $matches=function($name,$email,$phone,$title)use($q){if(!$q)return true;$hay=strtolower($name.' '.$email.' '.$phone.' '.$title);return strpos($hay,strtolower($q))!==false;};
    $date_ok=function($start)use($date_filter,$tz){if(!$date_filter)return true;return wp_date('Y-m-d',$start,$tz)===$date_filter;};
    $status_ok=function($row_status)use($status){if(!$status)return true;$row_status=$row_status==='scheduled'?'confirmed':$row_status;return $status==='scheduled' ? $row_status==='confirmed' : $row_status===$status;};

    /* The original booking table contains the historical records created by the
     * old scheduler. Keep these records as first-class bookings so revenue,
     * Google Meet links, paid/free history and appointments created before the
     * new scheduler all remain visible. */
    if($has_old){
        $old_rows=$wpdb->get_results("SELECT * FROM {$old_table} ORDER BY created_at DESC LIMIT 2000");
        foreach((array)$old_rows as $b){
            $name=trim(sanitize_text_field(($b->first_name??'').' '.($b->last_name??''))); if(!$name)$name='Booking #'.(int)$b->id;
            $email=sanitize_email($b->email??''); $phone=sanitize_text_field($b->phone??'');
            $title=sanitize_text_field($b->practice_type??''); if(!$title)$title='New Meeting';
            $raw_status=sanitize_key($b->status??'pending');
            $entry_status=in_array($raw_status,['confirmed','completed','cancelled','pending'],true)?$raw_status:'confirmed';
            $entry_status=$entry_status==='pending'?'pending':$entry_status;
            if(!$status_ok($entry_status)||!$matches($name,$email,$phone,$title))continue;
            $booking_date=sanitize_text_field($b->booking_date??''); $booking_time=sanitize_text_field($b->booking_time??'');
            if(!$booking_date||!$booking_time)continue;
            $entry_tz=sanitize_text_field($b->timezone??'');
            try{$btz=new DateTimeZone($entry_tz?:wp_timezone_string());}catch(Exception $e){$btz=$tz;}
            try{$dt=new DateTime(trim($booking_date.' '.$booking_time),$btz);}catch(Exception $e){continue;}
            if(!$date_ok($dt->getTimestamp()))continue;
            $start=$dt->getTimestamp(); $end=!empty($b->canonical_end)?strtotime($b->canonical_end.' UTC'):$start+1800;
            $key=strtolower($email).'|'.preg_replace('/\s+/',' ',trim($booking_date)).'|'.preg_replace('/\s+/',' ',trim($booking_time));
            $meeting=esc_url_raw($b->google_meet_link??'');$calendar=esc_url_raw($b->google_html_link??'');
            $answers=[]; if(!empty($b->custom_answers)){ $ca=json_decode((string)$b->custom_answers,true); if(is_array($ca)) $answers=$ca; }
            $out[]=(object)['id'=>(int)$b->id,'legacy_kind'=>'old','source'=>'legacy','form_entry_id'=>0,'title'=>$title,'invitee_name'=>$name,'invitee_email'=>$email,'invitee_phone'=>$phone,'start_at'=>wp_date('Y-m-d H:i:s',$start,$tz),'end_at'=>wp_date('Y-m-d H:i:s',$end,$tz),'timezone'=>$entry_tz?:$tz->getName(),'event_timezone'=>$entry_tz?:$tz->getName(),'status'=>$entry_status,'location'=>$meeting?'Google Meet':($calendar?'Calendar event':''),'meeting_url'=>$meeting,'calendar_url'=>$calendar,'google_event_id'=>sanitize_text_field($b->google_event_id??''),'payment_status'=>sanitize_key($b->payment_status??'unpaid'),'payment_amount'=>(float)($b->fee_amount??0),'payment_currency'=>sanitize_text_field($b->fee_currency??'USD'),'created_at'=>$b->created_at?:current_time('mysql'),'answers'=>wp_json_encode($answers),'legacy_entry_status'=>$raw_status,'legacy_form_id'=>0,'old_booking_id'=>(int)$b->id];
            $idx=count($out)-1; $old_index[$key]=$idx;
        }
    }

    /* Also include legacy form submissions that never produced an old booking
     * row. If an old row exists, enrich it instead of showing a duplicate. */
    if($has_forms && $has_entries){
        $forms=$wpdb->get_results("SELECT id,form_name,fields,settings FROM {$forms_table} ORDER BY id ASC");
        foreach((array)$forms as $form){
            $fields=json_decode((string)$form->fields,true); if(!is_array($fields))$fields=[];
            $date_key='';$time_key='';$name_key='';$email_key='';$phone_key='';
            foreach($fields as $f){$key=(string)($f['label']??'');$type=sanitize_key($f['type']??'');if(!$key)continue;
                if(!$date_key&&$type==='date')$date_key=$key;
                if(!$time_key&&in_array($type,['timeslot','time'],true))$time_key=$key;
                if(!$name_key&&in_array($type,['name','text'],true)&&preg_match('/\b(full\s+name|name)\b/i',$key))$name_key=$key;
                if(!$email_key&&$type==='email')$email_key=$key;
                if(!$phone_key&&$type==='phone')$phone_key=$key;
            }
            if(!$date_key||!$time_key)continue;
            $entries=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$entries_table} WHERE form_id=%d ORDER BY id DESC LIMIT 1000",(int)$form->id));
            foreach((array)$entries as $entry){
                $data=json_decode((string)$entry->entry_data,true);if(!is_array($data))continue;
                $entry_date=sanitize_text_field($data[$date_key]??'');$time=sanitize_text_field($data[$time_key]??'');if(!$entry_date||!$time)continue;
                $entry_tz=sanitize_text_field($data['__timezone_id__']??'');try{$et= new DateTimeZone($entry_tz?:wp_timezone_string());}catch(Exception $e){$et=$tz;}
                try{$dt=new DateTime(trim($entry_date.' '.$time),$et);}catch(Exception $e){continue;}
                $name=$name_key?sanitize_text_field($data[$name_key]??''):'';if(!$name){foreach($data as $k=>$v){if(stripos($k,'name')!==false&&!is_array($v)){ $name=sanitize_text_field($v);break; }}}
                if(!$name)$name='Form submission #'.(int)$entry->id;
                $email=$email_key?sanitize_email($data[$email_key]??''):'';$phone=$phone_key?sanitize_text_field($data[$phone_key]??''):'';$title=$form->form_name?:'Appointment Form';
                $entry_status=((string)$entry->status==='read')?'completed':'confirmed';
                if(!$status_ok($entry_status)||!$matches($name,$email,$phone,$title)||!$date_ok($dt->getTimestamp()))continue;
                $answers=$data;unset($answers[$date_key],$answers[$time_key]);
                $meeting='';$calendar='';$google_event_id='';
                foreach(['__meeting_url__','meeting_url','google_meet_link'] as $mk){if(!empty($data[$mk])&&is_string($data[$mk])){$meeting=esc_url_raw($data[$mk]);break;}}
                if(!empty($data['__calendar_url__'])&&is_string($data['__calendar_url__']))$calendar=esc_url_raw($data['__calendar_url__']);
                if(!empty($data['__google_event_id__'])&&is_string($data['__google_event_id__']))$google_event_id=sanitize_text_field($data['__google_event_id__']);
                $key=strtolower($email).'|'.preg_replace('/\s+/',' ',trim($entry_date)).'|'.preg_replace('/\s+/',' ',trim($time));
                if(isset($old_index[$key])){
                    $i=$old_index[$key];$o=$out[$i];
                    if(!$o->meeting_url&&$meeting)$o->meeting_url=$meeting;if(!$o->calendar_url&&$calendar)$o->calendar_url=$calendar;if(!$o->google_event_id&&$google_event_id)$o->google_event_id=$google_event_id;
                    if($o->payment_status==='unpaid'&&!empty($data['__payment_intent__']))$o->payment_status='paid';
                    $o->answers=wp_json_encode($answers);$o->form_entry_id=(int)$entry->id;$o->legacy_form_id=(int)$form->id;$o->title=$title?:$o->title;$o->location=$o->meeting_url?'Google Meet':($o->calendar_url?'Calendar event':$o->location);
                    continue;
                }
                $form_settings=json_decode((string)($form->settings??''),true); if(!is_array($form_settings))$form_settings=[]; $stripe_settings=(isset($form_settings['integrations']['stripe'])&&is_array($form_settings['integrations']['stripe']))?$form_settings['integrations']['stripe']:[];
                $out[]=(object)['id'=>(int)$entry->id,'legacy_kind'=>'entry','source'=>'legacy','form_entry_id'=>(int)$entry->id,'title'=>$title,'invitee_name'=>$name,'invitee_email'=>$email,'invitee_phone'=>$phone,'start_at'=>$dt->format('Y-m-d H:i:s'),'end_at'=>(clone $dt)->modify('+30 minutes')->format('Y-m-d H:i:s'),'timezone'=>$et->getName(),'event_timezone'=>$et->getName(),'status'=>$entry_status,'location'=>$meeting?'Google Meet':($calendar?'Calendar event':''),'meeting_url'=>$meeting,'calendar_url'=>$calendar,'google_event_id'=>$google_event_id,'payment_status'=>!empty($data['__payment_intent__'])?'paid':'none','payment_amount'=>!empty($data['__payment_intent__']) ? (float)($stripe_settings['amount']??0) : 0,'payment_currency'=>sanitize_text_field($stripe_settings['currency']??'USD'),'created_at'=>$entry->created_at?:current_time('mysql'),'answers'=>wp_json_encode($answers),'legacy_entry_status'=>$entry->status,'legacy_form_id'=>(int)$form->id,'old_booking_id'=>0];
            }
        }
    }
    return $out;
}

add_action('wp_ajax_fp_sched_admin_bookings',function(){
    if(!current_user_can('manage_options'))wp_send_json_error(['message'=>'Permission denied.'],403);
    check_ajax_referer('fp_sched_booking_admin','nonce');
    global $wpdb;$t=fp_sched_tables();$uid=get_current_user_id();$mode=sanitize_key($_POST['mode']??'list');
    $status=sanitize_key($_POST['status']??'');$q=sanitize_text_field(wp_unslash($_POST['q']??''));$date=sanitize_text_field(wp_unslash($_POST['date']??''));$tz=wp_timezone();
    $owner='e.user_id=%d';$args=[$uid];
    if($status){$owner.=' AND b.status=%s';$args[]=$status;}
    if($q){$like='%'.$wpdb->esc_like($q).'%';$owner.=' AND (b.invitee_name LIKE %s OR b.invitee_email LIKE %s OR b.invitee_phone LIKE %s OR e.title LIKE %s)';array_push($args,$like,$like,$like,$like);}
    $rows=$wpdb->get_results($wpdb->prepare("SELECT b.*,e.title,e.timezone AS event_timezone FROM {$t['bookings']} b INNER JOIN {$t['events']} e ON e.id=b.event_id WHERE $owner ORDER BY b.start_at DESC LIMIT 500",$args));
    if($date&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$rows=array_values(array_filter($rows,function($b)use($date,$tz){return wp_date('Y-m-d',strtotime($b->start_at.' UTC'),$tz)===$date;}));
    $legacy=fp_sched_legacy_appointment_rows($uid,$q,$status,$date);
    $all=array_merge((array)$rows,$legacy);
    usort($all,function($a,$b){return strcmp((string)$b->start_at,(string)$a->start_at);});
    if($mode==='detail'){
        $raw=wp_unslash($_POST['id']??'');
        if(strpos((string)$raw,'legacy-')===0){$parts=explode('-', (string)$raw);$kind=$parts[1]??'entry';$lid=absint($parts[2]??0);$legacy_rows=fp_sched_legacy_appointment_rows($uid);$b=null;foreach($legacy_rows as $x){if((int)$x->id===$lid && (($kind==='old' && (($x->legacy_kind??'entry')==='old')) || ($kind==='entry' && (($x->legacy_kind??'entry')==='entry')))){ $b=$x;break;}}if(!$b)wp_send_json_error(['message'=>'Booking not found.'],404);$a=json_decode($b->answers,true);if(!is_array($a))$a=[];$start=strtotime($b->start_at);wp_send_json_success(['booking'=>['id'=>'legacy-'.$kind.'-'.(int)$b->id,'source'=>'legacy','invitee_name'=>$b->invitee_name,'invitee_email'=>$b->invitee_email,'invitee_phone'=>$b->invitee_phone,'title'=>$b->title,'status'=>$b->status,'timezone'=>$b->timezone,'event_timezone'=>$b->event_timezone,'when'=>wp_date('F j, Y g:i A',$start,$tz),'host'=>'','location'=>$b->location?:'Not specified','payment_status'=>$b->payment_status,'payment_amount'=>$b->payment_amount??0,'payment_currency'=>$b->payment_currency??'USD','created'=>wp_date('F j, Y g:i A',strtotime($b->created_at),$tz),'meeting_url'=>$b->meeting_url??'','calendar_url'=>$b->calendar_url??''],'answers'=>$a]);}
        $id=absint($raw);$b=$wpdb->get_row($wpdb->prepare("SELECT b.*,e.title,e.timezone AS event_timezone FROM {$t['bookings']} b INNER JOIN {$t['events']} e ON e.id=b.event_id WHERE b.id=%d AND e.user_id=%d",$id,$uid));
        if(!$b)wp_send_json_error(['message'=>'Booking not found.'],404);$host=$b->host_user_id?get_userdata((int)$b->host_user_id):null;$a=json_decode($b->answers,true);if(!is_array($a))$a=[];$meeting=function_exists('fp_adv_booking_meeting_url')?fp_adv_booking_meeting_url($b->id):'';$start=strtotime($b->start_at.' UTC');wp_send_json_success(['booking'=>['id'=>(int)$b->id,'source'=>'native','invitee_name'=>$b->invitee_name,'invitee_email'=>$b->invitee_email,'invitee_phone'=>$b->invitee_phone,'title'=>$b->title,'status'=>$b->status,'timezone'=>$b->timezone,'event_timezone'=>$b->event_timezone,'when'=>wp_date('F j, Y g:i A',$start,$tz),'host'=>$host?$host->display_name:'','location'=>$b->location,'payment_status'=>$b->payment_status,'payment_amount'=>$b->payment_amount,'created'=>wp_date('F j, Y g:i A',strtotime($b->created_at),$tz),'meeting_url'=>$meeting],'answers'=>$a]);
    }
    if($mode==='status'){
        $raw=wp_unslash($_POST['id']??''); $new_status=sanitize_key($_POST['status']??''); if(!in_array($new_status,['scheduled','pending','confirmed','cancelled','completed'],true))wp_send_json_error(['message'=>'Invalid status.'],400);
        if(strpos((string)$raw,'legacy-')===0){
            $parts=explode('-',(string)$raw); $kind=$parts[1]??'entry'; $lid=absint($parts[2]??0);
            if($kind==='old'){
                $old_table=$wpdb->prefix.'schedule_bookings';
                $old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$old_table} WHERE id=%d",$lid)); if(!$old)wp_send_json_error(['message'=>'Booking not found.'],404);
                $ok=$wpdb->update($old_table,['status'=>$new_status==='scheduled'?'confirmed':$new_status,'updated_at'=>current_time('mysql')],['id'=>$lid]); if($ok===false)wp_send_json_error(['message'=>$wpdb->last_error?:'Could not update booking.'],500);
                wp_send_json_success(['status'=>$new_status]);
            }
            $entries_table=$wpdb->prefix.'ssb_form_entries'; $entry=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$entries_table} WHERE id=%d",$lid)); if(!$entry)wp_send_json_error(['message'=>'Form booking not found.'],404);
            $entry_status=$new_status==='cancelled'?'cancelled':($new_status==='completed'?'read':'unread'); $ok=$wpdb->update($entries_table,['status'=>$entry_status],['id'=>$lid]); if($ok===false)wp_send_json_error(['message'=>$wpdb->last_error?:'Could not update form booking.'],500);
            wp_send_json_success(['status'=>$new_status]);
        }
        $id=absint($raw);$new=sanitize_key($_POST['status']??'');if(!in_array($new,['scheduled','pending','cancelled','completed'],true))wp_send_json_error(['message'=>'Invalid status.'],400);$ok=$wpdb->query($wpdb->prepare("UPDATE {$t['bookings']} b INNER JOIN {$t['events']} e ON e.id=b.event_id SET b.status=%s,b.updated_at=%s WHERE b.id=%d AND e.user_id=%d",$new,current_time('mysql'),$id,$uid));if(!$ok&&$wpdb->last_error)wp_send_json_error(['message'=>$wpdb->last_error],500);fp_sched_log('booking.status_changed',$id,['status'=>$new],$uid);wp_send_json_success(['status'=>$new]);
    }
    $html='';$calendar=[];foreach($all as $b){$is_legacy=($b->source??'')==='legacy';$id_attr=$is_legacy?'legacy-'.(($b->legacy_kind??'entry')).'-'.(int)$b->id:(string)(int)$b->id;$initials=strtoupper(substr($b->invitee_name,0,1));$parts=preg_split('/\s+/',$b->invitee_name);if(count($parts)>1)$initials.=strtoupper(substr(end($parts),0,1));$start=strtotime($is_legacy?$b->start_at:$b->start_at.' UTC');$when=wp_date('M j, Y · g:i A',$start,$tz);$a=json_decode($b->answers??'{}',true);$n=is_array($a)?count($a):0;$badge=in_array($b->status,['scheduled','pending','confirmed','cancelled','completed'],true)?$b->status:'default';$calendar[]=['id'=>$id_attr,'local_date'=>wp_date('Y-m-d',$start,$tz),'local_time'=>wp_date('g:i A',$start,$tz),'invitee_name'=>$b->invitee_name,'title'=>$b->title];$html.='<article class="fp-booking-row" data-id="'.esc_attr($id_attr).'"><div class="fp-booking-avatar">'.esc_html($initials).'</div><div class="fp-booking-main"><div class="fp-booking-name"><strong>'.esc_html($b->invitee_name).'</strong><span class="fp-booking-badge '.esc_attr($badge).'">'.esc_html(ucfirst($b->status)).'</span></div><div class="fp-booking-event">'.esc_html($b->title).($is_legacy?' <span class="description">· Form booking</span>':'').'</div><div class="fp-booking-meta"><span>'.esc_html($when).'</span><span>'.esc_html($b->event_timezone?:$b->timezone).'</span></div></div><div class="fp-booking-contact">'.($b->invitee_email?'<a href="mailto:'.esc_attr($b->invitee_email).'">'.esc_html($b->invitee_email).'</a>':'').($b->invitee_phone?'<a href="tel:'.esc_attr($b->invitee_phone).'">'.esc_html($b->invitee_phone).'</a>':'').'</div><div class="fp-booking-summary"><span>'.esc_html($b->payment_status?:'unpaid').'</span>'.((float)$b->payment_amount>0?'<strong>'.esc_html(number_format((float)$b->payment_amount,2)).'</strong>':'').($n?'<small>'.(int)$n.' form answer'.($n===1?'':'s').'</small>':'').'</div><button type="button" class="button fp-booking-view" data-id="'.esc_attr($id_attr).'">View details</button></article>';}
    $total=count($all);$upcoming=0;$confirmed=0;$cancelled=0;$revenue=0;foreach($all as $b){$ts=strtotime($b->start_at.($b->source==='legacy'?'':' UTC'));if($ts>=time()&&!in_array($b->status,['cancelled','completed'],true))$upcoming++;if(in_array($b->status,['scheduled','confirmed'],true))$confirmed++;if($b->status==='cancelled')$cancelled++;if((float)($b->payment_amount??0)>0&&in_array(strtolower((string)($b->payment_status??'')),['paid','succeeded','success','completed','captured','requires_capture'],true))$revenue+=(float)$b->payment_amount;}
    wp_send_json_success(['html'=>$html,'bookings'=>$calendar,'stats'=>['total'=>$total,'upcoming'=>$upcoming,'confirmed'=>$confirmed,'cancelled'=>$cancelled,'revenue'=>$revenue]]);
});

add_action('rest_api_init',function(){register_rest_route('formpilot/v1','/availability/(?P<event_id>\d+)', ['methods'=>'GET','callback'=>function(WP_REST_Request $r){if(function_exists('fp_adv_public_guard')){$g=fp_adv_public_guard('availability',60);if(is_wp_error($g))return $g;}$date=sanitize_text_field($r['date']?:wp_date('Y-m-d'));return ['event_id'=>(int)$r['event_id'],'date'=>$date,'slots'=>fp_sched_available_slots((int)$r['event_id'],$date)];},'permission_callback'=>'__return_true']);register_rest_route('formpilot/v1','/booking',['methods'=>'POST','callback'=>function(WP_REST_Request $r){if(function_exists('fp_adv_public_guard')){$g=fp_adv_public_guard('booking',20);if(is_wp_error($g))return $g;}$idem=sanitize_text_field($r->get_header('idempotency-key'));if($idem){$cached=get_transient('fp_idem_'.md5($idem));if(is_array($cached))return $cached;}$e=fp_sched_event(absint($r['event_id']));if(!$e||!$e->active)return new WP_Error('event_not_found','Event not found',['status'=>404]);$name=sanitize_text_field($r['name']);$email=sanitize_email($r['email']);$phone=sanitize_text_field($r['phone']);$start=sanitize_text_field($r['start']);if(!$name||!is_email($email)||!$start)return new WP_Error('invalid','Name, email and start time are required.',['status'=>400]);$token=sanitize_text_field($r['single_use_token']??'');$claimed=false;if($token){global $wpdb;$tt=fp_sched_tables();$now=fp_sched_now();$wpdb->query($wpdb->prepare("UPDATE {$tt['links']} SET uses=uses+1 WHERE token=%s AND event_id=%d AND uses<max_uses AND (expires_at IS NULL OR expires_at='' OR expires_at >= %s)",$token,$e->id,$now));if($wpdb->rows_affected!==1)return new WP_Error('link_invalid','This single-use link is no longer valid.',['status'=>403]);$claimed=true;}$id=fp_sched_booking_create($e,$name,$email,$phone,$start,(array)$r['answers'],sanitize_text_field($r['payment_intent_id']??''));if(is_wp_error($id)){if($claimed)$wpdb->query($wpdb->prepare("UPDATE {$tt['links']} SET uses=GREATEST(0,uses-1) WHERE token=%s",$token));return $id;}global $wpdb;$tt=fp_sched_tables();$b=$wpdb->get_row($wpdb->prepare("SELECT manage_token,location,invoice_id FROM {$tt['bookings']} WHERE id=%d",$id));$resp=['success'=>true,'booking_id'=>$id,'manage_url'=>!empty($b->manage_token)?home_url('/?formpilot_manage='.$b->manage_token):'','location'=>$b->location??'','invoice_id'=>(int)($b->invoice_id??0)];if($idem)set_transient('fp_idem_'.md5($idem),$resp,10*MINUTE_IN_SECONDS);return $resp;},'permission_callback'=>'__return_true']);});

add_shortcode('formpilot_event',function($atts){$slug=sanitize_title($atts['slug']??'');if(!$slug&&isset($_GET['formpilot_event']))$slug=sanitize_title(wp_unslash($_GET['formpilot_event']));global $wpdb;$t=fp_sched_tables();$e=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['events']} WHERE slug=%s AND active=1",$slug));if(!$e)return '<p>Event not found.</p>';ob_start();?><div class="formpilot-scheduler" data-event="<?php echo (int)$e->id;?>" style="max-width:900px;margin:30px auto;padding:24px;border:1px solid #e5e7eb;border-radius:18px;background:#fff"><h2><?php echo esc_html($e->title);?></h2><p><?php echo esc_html($e->description);?></p><p><strong><?php echo (int)$e->duration;?> minutes</strong> · <?php echo esc_html($e->timezone);?></p><label>Date <input type="date" id="fp-date-<?php echo (int)$e->id;?>" value="<?php echo esc_attr(wp_date('Y-m-d',strtotime('+1 day')));?>"></label><button type="button" class="button" onclick="fpLoadSlots(<?php echo (int)$e->id;?>)">Show times</button><div id="fp-slots-<?php echo (int)$e->id;?>" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:8px;margin:20px 0"></div><form id="fp-book-<?php echo (int)$e->id;?>" style="display:none"><input type="hidden" name="formpilot_link_token" value="<?php echo isset($_GET['formpilot_link'])?esc_attr(sanitize_text_field(wp_unslash($_GET['formpilot_link']))):'';?>"><input type="hidden" name="event_id" value="<?php echo (int)$e->id;?>"><input type="hidden" name="start"><p><input name="name" placeholder="Full name" required></p><p><input name="email" type="email" placeholder="Email" required></p><p><input name="phone" placeholder="Phone"></p><button class="button button-primary">Book now</button><span class="fp-msg"></span></form></div><script>function fpLoadSlots(id){var d=document.getElementById('fp-date-'+id).value;fetch('<?php echo esc_url(rest_url('formpilot/v1/availability/')); ?>'+id+'?date='+encodeURIComponent(d)).then(r=>r.json()).then(x=>{var box=document.getElementById('fp-slots-'+id);box.innerHTML='';(x.slots||[]).forEach(function(s){var b=document.createElement('button');b.type='button';b.className='button';b.textContent=s.start.slice(11,16);b.onclick=function(){var f=document.getElementById('fp-book-'+id);f.style.display='block';f.elements.start.value=s.start;f.scrollIntoView({behavior:'smooth'});};box.appendChild(b);});});}document.getElementById('fp-book-<?php echo (int)$e->id;?>').addEventListener('submit',function(ev){ev.preventDefault();var f=ev.target;var d={event_id:id= <?php echo (int)$e->id;?>,name:f.name.value,email:f.email.value,phone:f.phone.value,start:f.start.value,single_use_token:f.formpilot_link_token?f.formpilot_link_token.value:''};fetch('<?php echo esc_url(rest_url('formpilot/v1/booking'));?>',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}).then(r=>r.json()).then(x=>{f.querySelector('.fp-msg').textContent=x.success?' Booking confirmed! ':' '+(x.message||'Could not book.');if(x.success)f.reset();});});fpLoadSlots(<?php echo (int)$e->id;?>);</script><?php return ob_get_clean();});

