add_action('rest_api_init',function(){
 register_rest_route('formpilot/v1','/routing/(?P<slug>[A-Za-z0-9_-]+)', ['methods'=>'GET','callback'=>function(WP_REST_Request $r){global $wpdb;$t=fp_sched_tables();$x=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['routing']} WHERE slug=%s AND active=1",sanitize_text_field($r['slug'])));if(!$x)return new WP_Error('not_found','Routing form not found',['status'=>404]);return ['id'=>(int)$x->id,'name'=>$x->name,'questions'=>json_decode($x->questions,true),'rules'=>json_decode($x->rules,true)];},'permission_callback'=>'__return_true']);
 register_rest_route('formpilot/v1','/routing/resolve',['methods'=>'POST','callback'=>function(WP_REST_Request $r){global $wpdb;$t=fp_sched_tables();$slug=sanitize_text_field($r['slug']);$x=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['routing']} WHERE slug=%s AND active=1",$slug));if(!$x)return new WP_Error('not_found','Routing form not found',['status'=>404]);$answers=(array)$r['answers'];$rules=json_decode($x->rules,true);$target=(int)$x->default_event_id;foreach((array)$rules as $rule){$k=sanitize_key($rule['if']??'');if($k&&isset($answers[$k])&&sanitize_text_field($answers[$k])===sanitize_text_field($rule['equals']??'')){$target=absint($rule['event_id']??$target);break;}}$e=fp_sched_event($target);if(!$e)return new WP_Error('no_event','No event matched',['status'=>404]);return ['event_id'=>(int)$e->id,'slug'=>$e->slug,'title'=>$e->title];},'permission_callback'=>'__return_true']);
 register_rest_route('formpilot/v1','/poll/(?P<id>\d+)/vote',['methods'=>'POST','callback'=>function(WP_REST_Request $r){if(!fp_sched_feature('meeting_polls'))return new WP_Error('upgrade_required','Meeting Polls require FormPilot Pro.',['status'=>403]);global $wpdb;$t=fp_sched_tables();$pid=absint($r['id']);$oid=absint($r['option_id']);$name=sanitize_text_field($r['name']);$email=sanitize_email($r['email']);$vote=(int)!empty($r['vote']);if(!$pid||!$oid||!$name||!is_email($email))return new WP_Error('invalid','Name, email and option are required.',['status'=>400]);$wpdb->query($wpdb->prepare("INSERT INTO {$t['poll_votes']} (poll_id,option_id,voter_name,voter_email,vote,created_at) VALUES (%d,%d,%s,%s,%d,%s) ON DUPLICATE KEY UPDATE vote=VALUES(vote),voter_name=VALUES(voter_name)",$pid,$oid,$name,$email,$vote,fp_sched_now()));return ['success'=>true];},'permission_callback'=>'__return_true']);
});
add_action('init',function(){
 if(is_admin())return; if(isset($_GET['formpilot_link'])){ $token=preg_replace('/[^A-Za-z0-9]/','',wp_unslash($_GET['formpilot_link'])); global $wpdb;$t=fp_sched_tables();$l=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['links']} WHERE token=%s",$token));if($l&&$l->uses<$l->max_uses&&(!$l->expires_at||strtotime($l->expires_at)>=current_time('timestamp'))){add_filter('the_content',function($c)use($l){$e=fp_sched_event($l->event_id);return $e?do_shortcode('[formpilot_event slug="'.esc_attr($e->slug).'"]'):$c;});}}
 if(isset($_GET['formpilot_routing'])){ $slug=sanitize_title(wp_unslash($_GET['formpilot_routing']));global $wpdb;$t=fp_sched_tables();$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['routing']} WHERE slug=%s AND active=1",$slug));if($r){add_filter('the_content',function($c)use($r){$q=json_decode($r->questions,true);$html='<div class="formpilot-routing"><h2>'.esc_html($r->name).'</h2><form onsubmit="return fpResolveRoute(this)">';foreach((array)$q as $x){$html.='<p><label>'.esc_html($x['label']??'Question').'<select name="'.esc_attr($x['key']??'q').'">';foreach((array)($x['options']??[]) as $o)$html.='<option value="'.esc_attr($o).'">'.esc_html($o).'</option>';$html.='</select></label></p>';}$html.='<button class="button button-primary">Continue</button></form></div><script>function fpResolveRoute(f){event.preventDefault();var a={};new FormData(f).forEach((v,k)=>a[k]=v);fetch("'.esc_url(rest_url('formpilot/v1/routing/resolve')).'",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({slug:"'.esc_js($r->slug).'",answers:a})}).then(x=>x.json()).then(x=>{if(x.slug)location.href="?formpilot_event="+encodeURIComponent(x.slug);else alert(x.message||"No matching event.");});return false;}</script>';return $html;});}}
});
